static void functions_clear(struct em_functions *members)
{
	*members = (struct em_functions){ 0 };
	members->state.name = "";
	members->state.start = -1;
}

static int functions_open(struct object *self, const struct vr *caller_context)
{
	OBS_OBJECT_OPEN_;
	if (self->ref_count == 1)
		functions_clear(self->members);
	return R_P;
}

static int functions_close(struct object *self,
	const struct vr *caller_context)
{
	struct em_functions *members = self->members;

	OBS_OBJECT_CLOSE_;
	if (!self->ref_count)
		functions_clear(members);
	return R_P;
}

static int functions_interact0(struct object *self, unsigned int action,
	const struct vr *caller_context)
{
	struct em_functions *members = self->members;

	if (action != NEOCC_AC0_FUNCTIONS_RESET) {
		SBO_OBJECT_INTERACT0;
	}

	if (!self->ref_count)
		return RN_INVALIDARG;
	functions_clear(members);
	return R_P;
}

static int functions_interact3(struct object *self, unsigned int action,
	unsigned char *input_stream, unsigned int quantity,
	unsigned char *output_stream, unsigned int capacity,
	unsigned int *output_quantity, const struct vr *caller_context)
{
	struct em_functions *members = self->members;
	struct neocc_function_temp_request request;
	struct neocc_function_temp_result result;
	struct neocc_function_temp *slot;
	int64_t offset;
	int i;

	*output_quantity = 0;
	if (action != NEOCC_AC3_FUNCTIONS_TEMP) {
		SBO_OBJECT_INTERACT3;
	}
	if (!self->ref_count || quantity != sizeof(request) ||
	    capacity < sizeof(result))
		return RN_INVALIDARG;
	memcpy(&request, input_stream, sizeof(request));
	if (request.size < 0 || request.alignment <= 0 ||
	    (request.alignment & (request.alignment - 1)))
		return RN_INVALIDARG;
	for (i = 0; i < members->temp_count; i++) {
		slot = members->temps + i;
		if (!(request.used & (1U << i)) &&
		    slot->size >= request.size &&
		    slot->alignment >= request.alignment) {
			result = (struct neocc_function_temp_result){
				slot->location, i };
			goto output;
		}
	}
	/* Preserve TinyCC's downward aligned allocation without signed overflow. */
	offset = ((int64_t)members->state.stack_offset - request.size) &
		-(int64_t)request.alignment;
	if (offset < INT_MIN || offset > INT_MAX)
		return RN_INVALIDARG;
	result = (struct neocc_function_temp_result){ (int)offset, -1 };
	members->state.stack_offset = result.offset;
	if (i < NEOCC_FUNCTION_TEMP_CAPACITY) {
		slot = members->temps + i;
		slot->location = result.offset;
		slot->size = request.size;
		slot->alignment = request.alignment;
		members->temp_count++;
		result.slot = i;
	}
output:
	memcpy(output_stream, &result, sizeof(result));
	*output_quantity = sizeof(result);
	return R_P;
}

