static int functions_interact1(struct object *self, unsigned int action,
	unsigned char *output_stream, unsigned int capacity,
	unsigned int *output_quantity, const struct vr *caller_context)
{
	struct em_functions *members = self->members;
	struct neocc_function *state = &members->state;

	*output_quantity = 0;
	if (action != NEOCC_AC1_FUNCTIONS_BORROW) {
		SBO_OBJECT_INTERACT1;
	}
	if (!self->ref_count || capacity < sizeof(state))
		return RN_INVALIDARG;
	memcpy(output_stream, &state, sizeof(state));
	*output_quantity = sizeof(state);
	return R_P;
}

static int functions_interact2(struct object *self, unsigned int action,
	unsigned char *input_stream, unsigned int quantity,
	const struct vr *caller_context)
{
	struct em_functions *members = self->members;
	struct neocc_function initial;

	if (action != NEOCC_AC2_FUNCTIONS_BEGIN) {
		SBO_OBJECT_INTERACT2;
	}
	if (!self->ref_count || quantity != sizeof(initial))
		return RN_INVALIDARG;
	memcpy(&initial, input_stream, sizeof(initial));
	if (!initial.name || initial.start < 0)
		return RN_INVALIDARG;
	functions_clear(members);
	members->state = initial;
	return R_P;
}

void tog_functions(struct object *object)
{
	object->open = functions_open;
	object->input = functions_input;
	object->output = functions_output;
	object->io_put = functions_io_put;
	object->interact0 = functions_interact0;
	object->interact1 = functions_interact1;
	object->interact2 = functions_interact2;
	object->interact3 = functions_interact3;
	object->close = functions_close;
}
